/**
 * Body for placing a new order
 */
export interface OrderInput {
  /** UUID of the item to order */
  itemId: string;
  /**
     * Quantity (positive integer 1-999); must be a whole number
     * @minimum 1
     * @maximum 999
     */
  qty: number;
  /**
     * Guest name (required after whitespace trimming)
     * @maxLength 200
     */
  guestName: string;
  /**
     * Guest phone number (required; must contain at least six digit characters; formatting is preserved)
     * @minLength 1
     * @maxLength 50
     */
  guestPhone: string;
  /**
     * Guest accommodation/unit pre-filled from sign-in but editable (e.g. "B-14")
     * @minLength 1
     * @maxLength 100
     */
  guestUnit: string;
  /**
     * Optional guest note
     * @maxLength 500
     */
  guestNote?: string;
  /**
     * Required only when the tenant has configured an order password; compared after trimming and remains case-sensitive
     * @maxLength 200
     */
  orderPassword?: string;
  /** UI language used for localized order validation errors; defaults to sl */
  lang?: OrderInputLang;
}

